30	    public int quote(List<Item> items) {
31	        BigDecimal policyBasePremium = MhpcoPriceList.policyBasePremiumOf(items);
32	        BigDecimal premiumBeforeFee = policyScopeContribution(policyBasePremium)
33	                .add(itemScopeContribution(items));
34	        contractsWritten++;
35	        return roundInOfficeFavour(premiumBeforeFee.add(PROCESSING_FEE));
36	    }
37	
