39	     * What the item scope contributes: the MHPCO charges a risk surcharge for each
40	     * risky item as a share of that item's own base premium, never of the policy total.
41	     */
42	    private static BigDecimal itemScopeContribution(List<Item> items) {
43	        return items.stream()
44	                .map(ClaimOffice::riskSurchargeFor)
45	                .reduce(BigDecimal.ZERO, BigDecimal::add);
46	    }
