49	        BigDecimal itemBasePremium = MhpcoPriceList.basePremiumOf(item);
50	        BigDecimal surcharge = BigDecimal.ZERO;
51	        if (item.cursed()) {
52	            surcharge = surcharge.add(shareOf(itemBasePremium, CURSE_SURCHARGE_RATE));
53	        }
54	        if (isHighlyEnchanted(item)) {
55	            surcharge = surcharge.add(
