import java.math.BigDecimal;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;

/**
 * The MHPCO price list: what the office charges as a base premium for the items it
 * covers, before any modifier that depends on the customer or the contract.
 */
public final class MhpcoPriceList {

    /** Base premium in G per main item type. */
    private static final Map<String, Integer> MAIN_ITEM_BASE_PREMIUM_BY_TYPE = Map.of(
            "sword", 100,
            "amulet", 60,
            "staff", 80,
            "potion", 40);

    /**
     * Components are a family of small item types the MHPCO prices alike: every
     * component costs the same base premium, whatever its type.
     */
    private static final Set<String> COMPONENT_TYPES = Set.of("rune", "moonstone");

    private static final int COMPONENT_BASE_PREMIUM = 25;

    /** A building block of exactly 3 alike components is offered at a special price. */
    private static final int COMPONENT_BLOCK_SIZE = 3;
    private static final int COMPONENT_BLOCK_BASE_PREMIUM = 60;

    /**
     * Placeholder for types not yet in the price list. The specification treats an
     * unknown type as an error; until that behavior is implemented, unlisted types
     * fall back to the sword price rather than to an invented "unlisted item" price.
     */
    private static final int UNLISTED_TYPE_PLACEHOLDER_PREMIUM =
            MAIN_ITEM_BASE_PREMIUM_BY_TYPE.get("sword");

    private MhpcoPriceList() {
    }

    /**
     * The policy base premium: every main item at its price-list premium, plus each
     * group of alike components priced together so building blocks can be recognised.
     */
    public static BigDecimal policyBasePremiumOf(List<Item> items) {
        BigDecimal mainItems = items.stream()
                .filter(item -> !isComponent(item))
                .map(MhpcoPriceList::mainItemBasePremiumOf)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        BigDecimal components = alikeComponentCounts(items).values().stream()
                .map(MhpcoPriceList::alikeComponentsBasePremiumOf)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        return mainItems.add(components);
    }

    /**
     * What a single item costs on its own, ignoring any building block it belongs to.
     * Item risk surcharges are shares of this amount.
     */
    public static BigDecimal basePremiumOf(Item item) {
        if (isComponent(item)) {
            return BigDecimal.valueOf(COMPONENT_BASE_PREMIUM);
        }
        return mainItemBasePremiumOf(item);
    }

    /** How many components of each type the policy covers, grouped by their type. */
    private static Map<String, Long> alikeComponentCounts(List<Item> items) {
        return items.stream()
                .filter(MhpcoPriceList::isComponent)
                .collect(Collectors.groupingBy(Item::type, Collectors.counting()));
    }

    /**
     * What the office charges for the alike components of one type: a building block
     * is offered at its special price, anything else is priced component by component.
     */
    private static BigDecimal alikeComponentsBasePremiumOf(long alikeCount) {
        if (formsBuildingBlock(alikeCount)) {
            return BigDecimal.valueOf(COMPONENT_BLOCK_BASE_PREMIUM);
        }
        return BigDecimal.valueOf(alikeCount * COMPONENT_BASE_PREMIUM);
    }

    /** The block price is offered for exactly 3 alike components -- no more, no less. */
    private static boolean formsBuildingBlock(long alikeCount) {
        return alikeCount == COMPONENT_BLOCK_SIZE;
    }

    private static BigDecimal mainItemBasePremiumOf(Item item) {
        return BigDecimal.valueOf(MAIN_ITEM_BASE_PREMIUM_BY_TYPE.getOrDefault(
                item.type(), UNLISTED_TYPE_PLACEHOLDER_PREMIUM));
    }

    private static boolean isComponent(Item item) {
        return COMPONENT_TYPES.contains(item.type());
    }
}
public record Customer(int yearsWithMHPCO) {
}
/**
 * An item a customer wishes to insure. Components such as runes carry no material
 * and no enchantment level; for them {@code material} is null and {@code enchantment}
 * is zero.
 */
public record Item(String type, String material, int enchantment, boolean cursed) {

    /** A plain item: no material recorded, unenchanted and not cursed. */
    public Item(String type) {
        this(type, null, 0, false);
    }
}
