import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.List;

public class ClaimOffice {

    private static final BigDecimal PROCESSING_FEE = BigDecimal.valueOf(5);
    private static final BigDecimal FIRST_INSURANCE_SURCHARGE_RATE = rate(10);
    private static final BigDecimal CURSE_SURCHARGE_RATE = rate(50);
    private static final BigDecimal HIGH_ENCHANTMENT_SURCHARGE_RATE = rate(30);

    private static final BigDecimal LOYALTY_DISCOUNT_RATE = rate(20);
    private static final BigDecimal FOLLOW_UP_CONTRACT_DISCOUNT_RATE = rate(15);

    /** From this many years of business on, the MHPCO calls a customer long-standing. */
    private static final int LONG_STANDING_YEARS = 2;

    /** From this enchantment level on, the MHPCO considers an item highly enchanted. */
    private static final int HIGH_ENCHANTMENT_LEVEL = 5;

    private final Customer customer;
    private final ContractHistory contractHistory = new ContractHistory();

    public ClaimOffice(Customer customer) {
        this.customer = customer;
    }

    /**
     * The office quotes the premium for the items and, in doing so, writes the
     * contract: the premium is priced against the customer's file as it stands, and
     * only then does the new contract enter that file.
     */
    public int quote(List<Item> items) {
        int premium = premiumFor(items);
        contractHistory.recordContractWritten();
        return premium;
    }

    /** What the office charges for these items: every scope's contribution, plus the fee. */
    private int premiumFor(List<Item> items) {
        BigDecimal policyBasePremium = MhpcoPriceList.policyBasePremiumOf(items);
        BigDecimal premiumBeforeFee = policyScopeContribution(policyBasePremium)
                .add(itemScopeContribution(items));
        return roundInOfficeFavour(premiumBeforeFee.add(PROCESSING_FEE));
    }

    /**
     * What the item scope contributes: the MHPCO charges a risk surcharge for each
     * risky item as a share of that item's own base premium, never of the policy total.
     */
    private static BigDecimal itemScopeContribution(List<Item> items) {
        return items.stream()
                .map(ClaimOffice::riskSurchargeFor)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    private static BigDecimal riskSurchargeFor(Item item) {
        BigDecimal itemBasePremium = MhpcoPriceList.basePremiumOf(item);
        BigDecimal surcharge = BigDecimal.ZERO;
        if (item.cursed()) {
            surcharge = surcharge.add(shareOf(itemBasePremium, CURSE_SURCHARGE_RATE));
        }
        if (isHighlyEnchanted(item)) {
            surcharge = surcharge.add(
                    shareOf(itemBasePremium, HIGH_ENCHANTMENT_SURCHARGE_RATE));
        }
        return surcharge;
    }

    private static boolean isHighlyEnchanted(Item item) {
        return item.enchantment() >= HIGH_ENCHANTMENT_LEVEL;
    }

    /**
     * What the policy scope contributes: the policy base premium itself, adjusted by
     * the modifiers the office applies to the policy as a whole.
     */
    private BigDecimal policyScopeContribution(BigDecimal policyBasePremium) {
        BigDecimal contribution = policyBasePremium
                .add(shareOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_RATE));
        if (isLongStanding()) {
            contribution = contribution
                    .subtract(shareOf(policyBasePremium, LOYALTY_DISCOUNT_RATE));
        }
        if (contractHistory.nextContractIsFollowUp()) {
            contribution = contribution
                    .subtract(shareOf(policyBasePremium, FOLLOW_UP_CONTRACT_DISCOUNT_RATE));
        }
        return contribution;
    }

    /** Two years of business with the MHPCO make a customer long-standing. */
    private boolean isLongStanding() {
        return customer.yearsWithMHPCO() >= LONG_STANDING_YEARS;
    }

    /** A modifier is a percentage share of the amount it applies to. */
    private static BigDecimal shareOf(BigDecimal amount, BigDecimal modifierRate) {
        return amount.multiply(modifierRate);
    }

    /** A modifier rate stated the way the price list states it: in whole percent. */
    private static BigDecimal rate(int percent) {
        return BigDecimal.valueOf(percent, 2);
    }

    /**
     * A premium is rounded up: the MHPCO rounds in its own favour. Intermediate
     * amounts stay exact fractions, so only this final step loses the remainder.
     */
    private static int roundInOfficeFavour(BigDecimal premium) {
        return premium.setScale(0, RoundingMode.CEILING).intValueExact();
    }
}
